import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Modifying Data in AL","description":"","frontmatter":{},"headers":[],"relativePath":"records-data-access-filtering-and-validation/modifying-data.md","filePath":"records-data-access-filtering-and-validation/modifying-data.md"}`),a={name:`records-data-access-filtering-and-validation/modifying-data.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="modifying-data-in-al" tabindex="-1">Modifying Data in AL <a class="header-anchor" href="#modifying-data-in-al" aria-label="Permalink to “Modifying Data in AL”">​</a></h1><p>AL provides methods for inserting, updating, and deleting records in Business Central tables.</p><h2 id="_1-insert" tabindex="-1">1. Insert() <a class="header-anchor" href="#_1-insert" aria-label="Permalink to “1. Insert()”">​</a></h2><p><code>Insert()</code> inserts a new record into a database table.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    ProductRec.Init();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ProductRec.&quot;No.&quot; := &#39;PROD001&#39;;</span></span>
<span class="line"><span>    ProductRec.Name := &#39;Laptop&#39;;</span></span>
<span class="line"><span>    ProductRec.Inventory := 20;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ProductRec.Insert();</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Key points:</p><ul><li><code>Init()</code> initializes the record&#39;s fields to their default values.</li><li>Assign values to the required fields before inserting.</li><li><code>Insert()</code> saves the new record to the database.</li><li>Returns <code>true</code> if successful, otherwise <code>false</code>.</li><li><code>Insert()</code> without arguments does not execute the table&#39;s <code>OnInsert</code> trigger.</li></ul><p>To execute the trigger:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Insert(true);</span></span></code></pre></div><h2 id="_2-validate" tabindex="-1">2. Validate() <a class="header-anchor" href="#_2-validate" aria-label="Permalink to “2. Validate()”">​</a></h2><p><code>Validate()</code> assigns a value to a field and executes that field&#39;s <code>OnValidate</code> trigger.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Validate(Name, &#39;Laptop&#39;);</span></span></code></pre></div><p>You can also validate a value that has already been assigned:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Name := &#39;Laptop&#39;;</span></span>
<span class="line"><span>ProductRec.Validate(Name);</span></span></code></pre></div><p><strong>Why use Validate() instead of direct assignment?</strong></p><p>Consider a field whose <code>OnValidate</code> trigger performs additional calculations or checks business rules.</p><p>Direct assignment:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Inventory := 20;</span></span></code></pre></div><p>Does not execute the field&#39;s <code>OnValidate</code> trigger.</p><p>Using Validate:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Validate(Inventory, 20);</span></span></code></pre></div><p>Executes the field&#39;s validation logic.</p><p><strong>Important:</strong> <code>Validate()</code> does not save the record to the database. You still need <code>Insert()</code> or <code>Modify()</code>.</p><h2 id="_3-modify" tabindex="-1">3. Modify() <a class="header-anchor" href="#_3-modify" aria-label="Permalink to “3. Modify()”">​</a></h2><p><code>Modify()</code> saves changes made to an existing record.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if ProductRec.Get(&#39;PROD001&#39;) then begin</span></span>
<span class="line"><span>    ProductRec.Validate(Name, &#39;Gaming Laptop&#39;);</span></span>
<span class="line"><span>    ProductRec.Modify();</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Key points:</p><ul><li>Used to update existing records.</li><li>Returns a Boolean indicating whether the operation succeeded.</li><li><code>Modify()</code> does not execute the table&#39;s <code>OnModify</code> trigger by default.</li><li>Use <code>Modify(true)</code> to execute the trigger.</li></ul><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Modify(true);</span></span></code></pre></div><h2 id="_4-delete" tabindex="-1">4. Delete() <a class="header-anchor" href="#_4-delete" aria-label="Permalink to “4. Delete()”">​</a></h2><p><code>Delete()</code> removes the current record from the database.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if ProductRec.Get(&#39;PROD001&#39;) then</span></span>
<span class="line"><span>    ProductRec.Delete();</span></span></code></pre></div><p>Key points:</p><ul><li>Deletes the current record.</li><li>Returns a Boolean indicating success.</li><li><code>Delete()</code> does not execute the table&#39;s <code>OnDelete</code> trigger by default.</li><li>Use <code>Delete(true)</code> to execute the trigger.</li></ul><h2 id="_5-deleteall" tabindex="-1">5. DeleteAll() <a class="header-anchor" href="#_5-deleteall" aria-label="Permalink to “5. DeleteAll()”">​</a></h2><p><code>DeleteAll()</code> deletes all records matching the current filters.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.SetRange(Status, ProductRec.Status::Inactive);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ProductRec.DeleteAll();</span></span></code></pre></div><p>This deletes all inactive products.</p><p><strong>Important:</strong></p><ul><li>If no filters are applied, <code>DeleteAll()</code> deletes every record in the table.</li><li>By default, the table&#39;s <code>OnDelete</code> trigger is not executed.</li><li>Use <code>DeleteAll(true)</code> to execute the <code>OnDelete</code> trigger.</li></ul><p>Be extremely careful when using this method without filters!</p><h2 id="_6-modifyall" tabindex="-1">6. ModifyAll() <a class="header-anchor" href="#_6-modifyall" aria-label="Permalink to “6. ModifyAll()”">​</a></h2><p><code>ModifyAll()</code> updates a particular field across all records matching the current filters.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to “Syntax”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>RecordVar.ModifyAll(Field, NewValue, RunTrigger);</span></span></code></pre></div><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.SetRange(Status, ProductRec.Status::Active);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ProductRec.ModifyAll(Status, ProductRec.Status::Inactive);</span></span></code></pre></div><p>This changes the status of all active products to inactive.</p><p>Key points:</p><ul><li>Updates multiple records at once.</li><li>Respects the current filters.</li><li>If no filters are applied, it updates all records in the table.</li><li>The optional <code>RunTrigger</code> parameter controls whether the table&#39;s <code>OnModify</code> trigger executes.</li><li>The field&#39;s <code>OnValidate</code> trigger is NEVER executed by <code>ModifyAll()</code>, even when <code>RunTrigger</code> is true.</li></ul><p><strong>Use it when you need to update the same field across multiple records without individually processing each record.</strong></p><h2 id="_7-quick-comparison" tabindex="-1">7. Quick Comparison <a class="header-anchor" href="#_7-quick-comparison" aria-label="Permalink to “7. Quick Comparison”">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Insert()</code></td><td>Creates a new record.</td></tr><tr><td><code>Validate()</code></td><td>Assigns a value and executes field validation logic.</td></tr><tr><td><code>Modify()</code></td><td>Saves changes to an existing record.</td></tr><tr><td><code>Delete()</code></td><td>Deletes the current record.</td></tr><tr><td><code>DeleteAll()</code></td><td>Deletes all records matching the current filters.</td></tr><tr><td><code>ModifyAll()</code></td><td>Updates a field across all matching records.</td></tr></tbody></table><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h2><ul><li><code>Insert()</code> creates records; <code>Modify()</code> updates existing records.</li><li><code>Validate()</code> executes field-level validation logic but does not save records.</li><li><code>Modify()</code> and <code>Delete()</code> operate on the current record.</li><li><code>DeleteAll()</code> and <code>ModifyAll()</code> operate on sets of records.</li><li>The optional <code>RunTrigger</code> parameter controls execution of the corresponding table trigger.</li><li><code>ModifyAll()</code> never executes field-level <code>OnValidate</code> triggers.</li><li>Always be careful with <code>DeleteAll()</code> and <code>ModifyAll()</code> when no filters are applied.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-insert--method" target="_blank" rel="noreferrer">Record.Insert()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-validate-method" target="_blank" rel="noreferrer">Record.Validate()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-modify-method" target="_blank" rel="noreferrer">Record.Modify()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-delete-method" target="_blank" rel="noreferrer">Record.Delete()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-deleteall-method" target="_blank" rel="noreferrer">Record.DeleteAll()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-modifyall-method" target="_blank" rel="noreferrer">Record.ModifyAll()</a></li></ul>`,57)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};